-- LOCAL FIXTURE ONLY. This is not a Supabase clean replay or PostGIS proof.
-- Run only in a newly created database whose name starts hungry_remediation_.
do $$begin if current_database() not like 'hungry_remediation_%' then raise exception 'isolated fixture database required';end if;end$$;
create schema auth;create schema storage;create schema extensions;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function auth.role() returns text language sql stable as $$select current_user::text$$;
create extension pg_trgm with schema extensions;
create domain public.geography as text;
create function public.st_makepoint(double precision,double precision) returns point language sql immutable as $$select point($1,$2)$$;
create function public.st_setsrid(point,integer) returns text language sql immutable as $$select $1::text$$;
create function public.st_distance(geography,geography) returns double precision language sql immutable as $$select 0::double precision$$;
create function public.st_dwithin(geography,geography,integer) returns boolean language sql immutable as $$select true$$;
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,metadata jsonb,unique(bucket_id,name));alter table storage.objects enable row level security;
create table user_profiles(id uuid primary key,display_name text,avatar_url text,dishes_reviewed integer default 0,stalls_visited integer default 0,favourites_count integer default 0,created_at timestamptz default now());
create table privacy_settings(user_id uuid primary key,account_visibility text default 'public');
create table follows(follower_id uuid,followee_id uuid,status text default 'pending',approved_at timestamptz,requested_at timestamptz default now(),updated_at timestamptz default now(),primary key(follower_id,followee_id));
create table user_blocks(blocker_id uuid,blocked_user_key text,primary key(blocker_id,blocked_user_key));
create function public.app_user_block_exists(uuid,uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_blocks where (blocker_id=$1 and blocked_user_key=$2::text) or (blocker_id=$2 and blocked_user_key=$1::text))$$;
create function public.can_read_author_content(uuid) returns boolean language sql stable security definer set search_path=public as $$select not app_user_block_exists(auth.uid(),$1) and ($1=auth.uid() or not exists(select 1 from privacy_settings where user_id=$1 and account_visibility='private') or exists(select 1 from follows where follower_id=auth.uid() and followee_id=$1 and status='approved'))$$;
create table public_profiles (like user_profiles including defaults);alter table public_profiles enable row level security;
create policy public_profiles_visible on public_profiles for select using(public.can_read_author_content(id));
create function public.fixture_sync_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public_profiles(id,display_name,avatar_url,dishes_reviewed,stalls_visited,favourites_count,created_at) values(new.id,new.display_name,new.avatar_url,new.dishes_reviewed,new.stalls_visited,new.favourites_count,new.created_at);return new;end$$;
create trigger fixture_sync_profile after insert on user_profiles for each row execute function fixture_sync_profile();
create table account_deletion_requests(id uuid primary key default gen_random_uuid(),user_id uuid,reason text,status text default 'requested',created_at timestamptz default now(),scheduled_for timestamptz default now()+interval '30 days',cancelled_at timestamptz,completed_at timestamptz);
create unique index active_deletions on account_deletion_requests(user_id) where status in ('requested','processing');
create table account_deletion_processing_events(request_id uuid,user_id uuid,event_type text,actor text);
create table buildings(id text primary key,name text,building_type text,latitude double precision not null,longitude double precision not null,location geography generated always as (st_setsrid(st_makepoint(longitude,latitude),4326)::geography) stored,address text,postal_code text,is_closed_today boolean default false);
create table venues(id text primary key,building_id text,name text,unit_number text default '',floor text default '',hygiene_grade text,is_open boolean default true,top_dish_id text,closure_notice text,live_crowd text,created_at timestamptz default now(),latitude double precision,longitude double precision,location geography generated always as (st_setsrid(st_makepoint(longitude,latitude),4326)::geography) stored,address text,postal_code text,operating_hours text,image_url text,cuisine_tags text[] default '{}',dietary_tags text[] default '{}',media_approved_for_display boolean default false,media_rights_status text default 'unverified',media_source_url text,media_verified_at timestamptz,media_verified_by uuid,menu_approved_for_display boolean default false,menu_rights_status text default 'unverified',menu_source_url text,menu_verified_at timestamptz,menu_verified_by uuid);
create table dishes(id text primary key,venue_id text,building_id text,name text,description text,image_url text,blurhash text,distance_meters integer default 0,rating_avg numeric default 0,review_count integer default 0,price numeric default 0,price_range text,live_crowd text,taste_tags text[] default '{}',must_order boolean default false,availability_flags text[] default '{}',cuisine_tags text[] default '{}',created_at timestamptz default now(),media_approved_for_display boolean default false,media_rights_status text default 'unverified',media_source_url text,media_verified_at timestamptz,media_verified_by uuid,menu_approved_for_display boolean default false,menu_rights_status text default 'unverified',menu_source_url text,menu_verified_at timestamptz,menu_verified_by uuid);
create table dish_images(id uuid primary key default gen_random_uuid(),dish_id text,url text,sort_order integer,media_approved_for_display boolean default false,media_rights_status text default 'unverified',media_source_url text,media_verified_at timestamptz,media_verified_by uuid);
create table dish_taste_vectors(dish_id text primary key,source text default 'default',confidence numeric default 1,sweet numeric,spicy numeric,sour numeric,salty numeric,rich numeric,aromatic numeric);
create table user_favourite_dishes(user_id uuid,dish_id text);
create table dietary_flags(id uuid primary key default gen_random_uuid(),slug text);
create table dish_dietary_flags(dish_id text,dietary_flag_id uuid);
create table areas(name text,name_normalized text,center_lat double precision,center_lng double precision);
create function public.catalog_menu_is_displayable(boolean,text,text) returns boolean language sql immutable as $$select coalesce($1,false)$$;
create function public.catalog_display_image_url(text,boolean,text,text) returns text language sql immutable as $$select case when $2 then $1 end$$;
create table merchant_accounts(id uuid primary key default gen_random_uuid(),user_id uuid);
create table merchant_roles(merchant_account_id uuid,user_id uuid,role text);
create table merchant_outlets(id uuid primary key default gen_random_uuid(),merchant_account_id uuid,venue_id text,name text,business_type text,location_privacy text,building_id text,is_live boolean default false);
create table merchant_promotions(id uuid primary key default gen_random_uuid(),outlet_id uuid);
create table merchant_verifications(id uuid primary key default gen_random_uuid(),outlet_id uuid unique,status text,method text,submitted_at timestamptz,verified_at timestamptz,rejected_at timestamptz,rejection_reason text,expires_at timestamptz,updated_at timestamptz default now());
create table merchant_verification_evidence(id uuid primary key default gen_random_uuid(),verification_id uuid,method text,uploaded_by uuid,storage_bucket text,storage_path text,review_note text);
create function merchant_outlet_matches_catalog_link(text,text) returns boolean language sql stable as $$select exists(select 1 from merchant_outlets where venue_id=$1 and building_id=$2)$$;
create table dishes_draft(id uuid primary key default gen_random_uuid(),venue_id text,building_id text,name text,name_normalized text,price_cents integer,review_status text default 'pending',promoted_dish_id text,reviewed_by uuid,reviewed_at timestamptz,updated_at timestamptz default now(),created_at timestamptz default now());
create table portfolios(id uuid primary key default gen_random_uuid(),owner_id uuid references user_profiles(id),name text,description text,type text,visibility text,published_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table portfolio_items(id uuid primary key default gen_random_uuid(),portfolio_id uuid references portfolios(id) on delete cascade,item_type text,dish_id text,stall_id text,score integer check(score between 1 and 10),public_notes text,private_notes text,position integer default 0,created_at timestamptz default now(),updated_at timestamptz default now(),check((item_type='dish' and dish_id is not null and stall_id is null) or (item_type='stall' and stall_id is not null and dish_id is null)));
create table portfolio_collaborators(id uuid primary key default gen_random_uuid(),portfolio_id uuid,user_id uuid,role text,unique(portfolio_id,user_id));
create table portfolio_follows(user_id uuid,portfolio_id uuid,primary key(user_id,portfolio_id));
create table portfolio_flags(portfolio_id uuid,status text);
alter table portfolios enable row level security;alter table portfolio_items enable row level security;alter table portfolio_collaborators enable row level security;alter table portfolio_follows enable row level security;alter table venues enable row level security;alter table dishes enable row level security;
create policy fixture_venues_read on venues for select using(true);create policy fixture_dishes_read on dishes for select using(true);
create policy fixture_venues_update on venues for update using(true) with check(true);create policy fixture_dishes_write on dishes for all using(true) with check(true);
create function public.assert_portfolio_expected_updated_at(uuid,timestamptz) returns void language plpgsql set search_path=public as $$begin if $2 is not null and not exists(select 1 from portfolios where id=$1 and updated_at=$2) then raise exception 'Version conflict' using errcode='40001';end if;end$$;
create function public.record_passport_progress(text,text,text) returns void language sql as $$select$$;
create table catalog_raw_venue_cards(release_id uuid,id text,building_id text,building_name text,unit_number text,floor text,address text,postal_code text,latitude double precision,longitude double precision,listing_location geography);
create table catalog_raw_dish_cards(release_id uuid,id text,venue_id text,building_id text,building_name text,listing_location geography);
create table reviews(id uuid primary key,user_id uuid,dish_id text,venue_id text,author_name text,rating numeric,text text,tags text[],would_recommend boolean,created_at timestamptz default now());
create table review_photos(id uuid primary key default gen_random_uuid(),review_id uuid references reviews(id),url text,sort_order integer,storage_bucket text,storage_path text,unique(review_id,sort_order));
grant usage on schema public,auth,storage,extensions to anon,authenticated,service_role;
grant select,insert,update,delete on all tables in schema public,storage to authenticated;
grant select on all tables in schema public to anon;
